const animals=[{label:'パンダ',n:3},{label:'ネコ',n:2},{label:'フクロウ',n:1}];const svg=d3.select('#scene').append('svg').attr('viewBox','0 0 640 260');
function draw(){const size=d3.scaleSqrt().domain([0,30]).range([0,75]);svg.selectAll('circle').data(animals,d=>d.label).join('circle').attr('cx',(_,i)=>105+i*205).attr('cy',120).attr('fill',(_,i)=>['#73b8c2','#f5b265','#94bd9a'][i]).transition().duration(200).attr('r',d=>size(d.n));svg.selectAll('text').data(animals,d=>d.label).join('text').attr('x',(_,i)=>105+i*205).attr('y',230).attr('text-anchor','middle').text(d=>d.label+' '+d.n+'票');document.querySelector('#status').textContent='SUCCESS: 合計 '+animals.reduce((a,b)=>a+b.n,0)+'票（架空）';}
document.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>{animals[Number(b.dataset.vote)].n++;draw()});document.querySelector('#reset').onclick=()=>{animals.forEach(x=>x.n=0);draw()};draw();
